import{_ as e,o as d,c as o,a2 as r}from"./chunks/framework.mRCPFc5l.js";const p=JSON.parse('{"title":"Tracking Tables","description":"","frontmatter":{},"headers":[],"relativePath":"reference/tracking-tables.md","filePath":"reference/tracking-tables.md"}'),a={name:"reference/tracking-tables.md"};function c(i,t,n,l,s,h){return d(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="tracking-tables" tabindex="-1">Tracking Tables <a class="header-anchor" href="#tracking-tables" aria-label="Permalink to &quot;Tracking Tables&quot;">​</a></h1><p><code>dbsh init</code> creates three tables in your database. These track migration state, prevent concurrent deploys, and maintain an audit trail.</p><h2 id="migration-history" tabindex="-1"><code>__migration_history</code> <a class="header-anchor" href="#migration-history" aria-label="Permalink to &quot;`__migration_history`&quot;">​</a></h2><p>One row per applied migration per environment.</p><table tabindex="0"><thead><tr><th>Column</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>UUID/GUID</td><td>Primary key</td></tr><tr><td><code>version</code></td><td>VARCHAR</td><td>Migration version (e.g., <code>001</code>) or <code>R</code> for repeatables</td></tr><tr><td><code>name</code></td><td>VARCHAR</td><td>Migration name</td></tr><tr><td><code>script_name</code></td><td>VARCHAR</td><td>Filename (e.g., <code>V001__CreateUsers.sql</code>)</td></tr><tr><td><code>script_hash</code></td><td>VARCHAR</td><td>SHA-256 checksum of the script content</td></tr><tr><td><code>migration_type</code></td><td>VARCHAR</td><td>Schema, Data, Patch, or Repeatable</td></tr><tr><td><code>category</code></td><td>VARCHAR</td><td>Category (e.g., Schema, Data, Patch)</td></tr><tr><td><code>executed_by</code></td><td>VARCHAR</td><td>User or identity that ran the migration</td></tr><tr><td><code>executed_at_utc</code></td><td>TIMESTAMP</td><td>When the migration was applied</td></tr><tr><td><code>execution_time_ms</code></td><td>BIGINT</td><td>How long the migration took</td></tr><tr><td><code>environment</code></td><td>VARCHAR</td><td>Target environment name</td></tr><tr><td><code>status</code></td><td>VARCHAR</td><td>Completed, Failed, InProgress, or RolledBack</td></tr><tr><td><code>rollback_available</code></td><td>BOOLEAN</td><td>Whether a U script exists for this version</td></tr><tr><td><code>rollback_script_name</code></td><td>VARCHAR</td><td>Filename of the rollback script</td></tr><tr><td><code>error_message</code></td><td>TEXT</td><td>Error details if the migration failed</td></tr><tr><td><code>batch_number</code></td><td>INTEGER</td><td>Batch number for grouped executions</td></tr></tbody></table><p><strong>Unique constraints:</strong></p><ul><li><code>(script_name, environment)</code> — each script applied once per environment</li><li><code>(version, environment)</code> WHERE <code>version &lt;&gt; &#39;R&#39;</code> — one versioned migration per version per environment</li></ul><h2 id="migration-lock" tabindex="-1"><code>__migration_lock</code> <a class="header-anchor" href="#migration-lock" aria-label="Permalink to &quot;`__migration_lock`&quot;">​</a></h2><p>Distributed lock preventing concurrent deploys.</p><table tabindex="0"><thead><tr><th>Column</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>UUID/GUID</td><td>Primary key</td></tr><tr><td><code>lock_key</code></td><td>VARCHAR</td><td>Lock identifier</td></tr><tr><td><code>locked_by</code></td><td>VARCHAR</td><td>Owner identity</td></tr><tr><td><code>locked_at_utc</code></td><td>TIMESTAMP</td><td>When the lock was acquired</td></tr><tr><td><code>expires_at_utc</code></td><td>TIMESTAMP</td><td>When the lock expires (lease-based)</td></tr><tr><td><code>environment</code></td><td>VARCHAR</td><td>Target environment</td></tr><tr><td><code>is_active</code></td><td>BOOLEAN</td><td>Whether the lock is currently held</td></tr></tbody></table><p>The lock uses lease-based expiry with automatic renewal during batch execution. This means a crashed deployment won&#39;t block future runs indefinitely — the lock expires after <code>lockTimeoutSeconds</code>.</p><h2 id="migration-audit" tabindex="-1"><code>__migration_audit</code> <a class="header-anchor" href="#migration-audit" aria-label="Permalink to &quot;`__migration_audit`&quot;">​</a></h2><p>Append-only audit trail of every action.</p><table tabindex="0"><thead><tr><th>Column</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>UUID/GUID</td><td>Primary key</td></tr><tr><td><code>action</code></td><td>VARCHAR</td><td>Validate, DryRun, Deploy, Rollback, or Repair</td></tr><tr><td><code>performed_by</code></td><td>VARCHAR</td><td>User or identity</td></tr><tr><td><code>performed_at_utc</code></td><td>TIMESTAMP</td><td>When the action was performed</td></tr><tr><td><code>environment</code></td><td>VARCHAR</td><td>Target environment</td></tr><tr><td><code>details</code></td><td>TEXT</td><td>JSON or text details about the action</td></tr></tbody></table><h2 id="engine-specific-ddl" tabindex="-1">Engine-specific DDL <a class="header-anchor" href="#engine-specific-ddl" aria-label="Permalink to &quot;Engine-specific DDL&quot;">​</a></h2><p>The tracking table DDL differs between providers:</p><table tabindex="0"><thead><tr><th>Concern</th><th>PostgreSQL</th><th>SQL Server</th><th>MySQL</th><th>SQLite</th></tr></thead><tbody><tr><td>UUID column</td><td><code>UUID</code></td><td><code>UNIQUEIDENTIFIER</code></td><td><code>CHAR(36)</code></td><td><code>TEXT</code></td></tr><tr><td>Boolean column</td><td><code>BOOLEAN</code></td><td><code>BIT</code></td><td><code>TINYINT(1)</code></td><td><code>INTEGER</code> (0/1)</td></tr><tr><td>Timestamp column</td><td><code>TIMESTAMPTZ</code></td><td><code>DATETIME2</code></td><td><code>DATETIME</code></td><td><code>TEXT</code></td></tr><tr><td>ID default</td><td><code>gen_random_uuid()</code></td><td><code>NEWID()</code></td><td>C# Guid</td><td>C# Guid</td></tr></tbody></table>',17)])])}const _=e(a,[["render",c]]);export{p as __pageData,_ as default};
